figures.asymptoteSource:
// The reflection that makes a without-loss-of-generality step legitimate.
// Two-argument size fixes the output box at 320 x 120, so the declared
// aspect ratio 8/3 is exact and the reserved space cannot drift.
size(320,120);
pair A=(-6,0), B=(6,0);
draw(A--B,Arrow);
label("$x$",B,SE);
for (int t = -6; t <= 6; ++t) {
  draw((t,-0.1)--(t,0.1),gray);
}
dot((-1.5,0), black+2.5pt);
dot((1.5,0), black+2.5pt);
label("$a$",(-1.5,0.45),NW);
label("$b$",(1.5,0.45),NE);
draw((-1.5,0.28)--(1.5,0.28),red+1pt);
draw((1.5,0.28)--(-1.5,0.28),red+1pt);
label("swapping $a$ and $b$ reflects the picture",(0,-1.15),S);
